#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using MukioI18n;
using MVZ2.IO;
using MVZ2.Managers;
using MVZ2.ResourcePacks;
using MVZ2.UI.Addons;
using MVZ2Logic.Localization;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Addons
{
    public class ResourcePacksController : MonoBehaviour
    {
        public async Task Display()
        {
            // 加载语言包引用。
            await RefreshLanguagePacks();
            references.Clear();
            references.AddRange(Main.ResourcePackManager.GetAllResourcePackReferences());
            var originPreference = Main.ResourcePackManager.GetEnabledLanguagePackList();
            enabledReferences.Clear();
            enabledReferences.AddRange(originPreference);

            gameObject.SetActive(true);

            // 更新UI。
            CancelSelection();
            UpdateLanguagePacks();
        }
        public void Hide()
        {
            gameObject.SetActive(false);
        }
        #region 生命周期
        private void Awake()
        {
            ui.OnButtonClick += OnButtonClickCallback;
            ui.OnPackItemToggled += OnPackItemToggledCallback;
        }
        private async void Update()
        {
            refreshInterval -= Time.deltaTime;
            if (refreshInterval <= 0)
            {
                await RefreshLanguagePacks();
            }
        }
        #endregion

        #region 事件回调
        private async void OnButtonClickCallback(ResourcePacksUI.Buttons button)
        {
            switch (button)
            {
                case ResourcePacksUI.Buttons.Return:
                    if (!IsDirty())
                    {
                        Return();
                        break;
                    }
                    if (Main.ResourcePackManager.HasOutdatedEnabledPacks(enabledReferences))
                    {
                        var title = Main.LanguageManager._(LogicStrings.WARNING);
                        var desc = Main.LanguageManager._(WARNING_OUTDATED_LANGAUGE_PACK);
                        if (await Main.Scene.ShowDialogSelectAsync(title, desc))
                        {
                            await ReloadLanguagePacks();
                            Return();
                        }
                    }
                    else
                    {
                        await ReloadLanguagePacks();
                        Return();
                    }
                    break;
                case ResourcePacksUI.Buttons.Import:
                    {
                        await FileHelper.OpenExternalFile(new string[] { "zip" }, importAction);
                        async void importAction(string path)
                        {
                            addons.SetLoadingVisible(true);
                            try
                            {
                                var key = Main.ResourcePackManager.GetImportKey(path);
                                if (!string.IsNullOrEmpty(key))
                                {
                                    var reference = references.FirstOrDefault(r => r.GetKey() == key);
                                    if (reference != null)
                                    {
                                        var metadata = Main.ResourcePackManager.GetResourcePackMetadata(reference);
                                        var languagePackName = metadata?.name ?? key;
                                        var title = Main.LanguageManager._(LogicStrings.WARNING);
                                        var desc = Main.LanguageManager._(WARNING_OVERRIDE_LANGUAGE_PACK, languagePackName);
                                        var result = await Main.Scene.ShowDialogSelectAsync(title, desc);
                                        if (!result)
                                        {
                                            return;
                                        }
                                        Main.ResourcePackManager.DeleteLanguagePack(reference);
                                        overridedFile = true;
                                    }
                                    if (!await Main.ResourcePackManager.ValidateLanguagePack(path))
                                    {
                                        var title = Main.LanguageManager._(LogicStrings.ERROR);
                                        var desc = Main.LanguageManager._(ERROR_FAILED_TO_IMPORT);
                                        Main.Scene.ShowDialogMessage(title, desc);
                                        return;
                                    }
                                    Main.ResourcePackManager.ImportLanguagePack(path);
                                    await RefreshLanguagePacks();
                                }
                            }
                            catch (Exception e)
                            {
                                Debug.LogError($"导入语言包时出现错误：{e}");
                            }
                            finally
                            {
                                addons.SetLoadingVisible(false);
                            }
                        }
                    }
                    break;
                case ResourcePacksUI.Buttons.Export:
                    {
                        var selected = selectedLanguagePack;
                        if (selected != null)
                        {
                            var key = selected.GetKey();
                            bool success = false;
                            var fileName = Path.GetFileNameWithoutExtension(selected.GetFileName());
                            var path = await FileHelper.SaveExternalFile(fileName, new string[] { "zip" }, async dest =>
                            {
                                if (!references.Contains(selected))
                                    return;
                                success = await Main.ResourcePackManager.ExportLanguagePack(selected, dest);
                            });
                            if (string.IsNullOrEmpty(path))
                                break;
                            if (!success)
                            {
                                var title = Main.LanguageManager._(LogicStrings.ERROR);
                                var desc = Main.LanguageManager._(ERROR_NOT_SAVED);
                                await Main.Scene.ShowDialogMessageAsync(title, desc);
                            }
                            else
                            {
                                var title = Main.LanguageManager._(LogicStrings.HINT);
                                var desc = Main.LanguageManager._(HINT_SAVED, path);
                                await Main.Scene.ShowDialogMessageAsync(title, desc);
                            }
                        }
                    }
                    break;
                case ResourcePacksUI.Buttons.Delete:
                    {
                        var selected = selectedLanguagePack;
                        if (selected != null)
                        {
                            var key = selected.GetFileName();
                            var metadata = Main.ResourcePackManager.GetResourcePackMetadata(selected);
                            var languagePackName = metadata?.name ?? key;
                            var title = Main.LanguageManager._(LogicStrings.WARNING);
                            var desc = Main.LanguageManager._(WARNING_DELETE_LANGUAGE_PACK, languagePackName);
                            var result = await Main.Scene.ShowDialogSelectAsync(title, desc);
                            if (result)
                            {
                                Main.ResourcePackManager.DeleteLanguagePack(selected);
                                await RefreshLanguagePacks();
                            }
                        }
                    }
                    break;
                case ResourcePacksUI.Buttons.Disable:
                    if (selectedLanguagePack != null)
                    {
                        var index = enabledReferences.IndexOf(selectedLanguagePack);

                        enabledReferences.Remove(selectedLanguagePack);

                        if (enabledReferences.Count > 0)
                        {
                            var needSelectIndex = Mathf.Clamp(index, 0, enabledReferences.Count - 1);
                            selectedLanguagePack = enabledReferences[needSelectIndex];
                        }

                        UpdateLanguagePacks();
                        UpdateButtonInteractions();
                    }
                    break;
                case ResourcePacksUI.Buttons.Enable:
                    if (selectedLanguagePack != null && !enabledReferences.Contains(selectedLanguagePack))
                    {
                        var disabled = GetDisabledReferences().ToArray();
                        var index = Array.IndexOf(disabled, selectedLanguagePack);

                        enabledReferences.Insert(0, selectedLanguagePack);

                        var newDisabled = GetDisabledReferences().ToArray();
                        if (newDisabled.Length > 0)
                        {
                            var needSelectIndex = Mathf.Clamp(index, 0, newDisabled.Length - 1);
                            selectedLanguagePack = newDisabled[needSelectIndex];
                        }

                        UpdateLanguagePacks();
                        UpdateButtonInteractions();
                    }
                    break;
                case ResourcePacksUI.Buttons.MoveUp:
                    if (selectedLanguagePack != null && enabledReferences.Contains(selectedLanguagePack))
                    {
                        var index = enabledReferences.IndexOf(selectedLanguagePack);
                        if (index > 0)
                        {
                            enabledReferences.RemoveAt(index);
                            enabledReferences.Insert(index - 1, selectedLanguagePack);
                            UpdateLanguagePacks();
                            UpdateButtonInteractions();
                        }
                    }
                    break;
                case ResourcePacksUI.Buttons.MoveDown:
                    if (selectedLanguagePack != null && enabledReferences.Contains(selectedLanguagePack))
                    {
                        var index = enabledReferences.IndexOf(selectedLanguagePack);
                        if (index < enabledReferences.Count - 1)
                        {
                            enabledReferences.RemoveAt(index);
                            enabledReferences.Insert(index + 1, selectedLanguagePack);
                            UpdateLanguagePacks();
                            UpdateButtonInteractions();
                        }
                    }
                    break;
            }
        }
        private void OnPackItemToggledCallback(bool enabled, int index, bool value)
        {
            var reference = GetLanguagePackReferenceByUI(enabled, index);
            if (value)
            {
                selectedLanguagePack = reference;
                UpdateButtonInteractions();
            }
            else if (selectedLanguagePack == reference)
            {
                selectedLanguagePack = null;
                UpdateButtonInteractions();
            }
        }
        #endregion

        private async Task RefreshLanguagePacks()
        {
            refreshInterval = maxRefreshInterval;
            bool changed = await Main.ResourcePackManager.RefreshLanguagePackReferences();
            if (changed)
            {
                references.Clear();
                references.AddRange(Main.ResourcePackManager.GetAllResourcePackReferences());
                enabledReferences.RemoveAll(r => !references.Contains(r));
                UpdateLanguagePacks();
                CancelSelection();
            }
        }
        private async Task ReloadLanguagePacks()
        {
            overridedFile = false;
            addons.SetLoadingVisible(true);
            await Main.ResourcePackManager.ReloadLanguagePacks(enabledReferences.ToArray());
            addons.SetLoadingVisible(false);
        }
        private void Return()
        {
            Hide();
            addons.DisplayIndex();

            var musicID = Main.MusicManager.GetCurrentMusicID();
            if (NamespaceID.IsValid(musicID))
            {
                Main.MusicManager.Play(musicID);
            }
        }
        private void CancelSelection()
        {
            selectedLanguagePack = null;
            ui.DeselectAll();
            UpdateButtonInteractions();
        }
        private void UpdateLanguagePacks()
        {
            var disabled = GetDisabledReferences();
            var disabledViewDatas = new List<ResourcePackViewData>();
            var enabledViewDatas = new List<ResourcePackViewData>();
            foreach (var reference in disabled)
            {
                var metadata = Main.ResourcePackManager.GetResourcePackMetadata(reference);
                if (metadata == null)
                    continue;
                disabledViewDatas.Add(GetResourcePackViewData(metadata, reference));
            }
            foreach (var reference in enabledReferences)
            {
                var metadata = Main.ResourcePackManager.GetResourcePackMetadata(reference);
                if (metadata == null)
                    continue;
                enabledViewDatas.Add(GetResourcePackViewData(metadata, reference));
            }
            ui.SetDisabledLanguagePacks(disabledViewDatas.ToArray());
            ui.SetEnabledLanguagePacks(enabledViewDatas.ToArray());
        }
        private void UpdateButtonInteractions()
        {
            bool selected = selectedLanguagePack != null;
            bool isBuiltin = selectedLanguagePack != null && selectedLanguagePack.IsBuiltin;
            bool enabled = selectedLanguagePack != null && enabledReferences.Contains(selectedLanguagePack);
            int index = selectedLanguagePack != null ? enabledReferences.IndexOf(selectedLanguagePack) : -1;
            ui.SetButtonInteractable(ResourcePacksUI.Buttons.Delete, selected && !isBuiltin);
            ui.SetButtonInteractable(ResourcePacksUI.Buttons.Export, selected);
            ui.SetButtonInteractable(ResourcePacksUI.Buttons.Disable, enabled && selected && !isBuiltin);
            ui.SetButtonInteractable(ResourcePacksUI.Buttons.Enable, !enabled && selected && !isBuiltin);
            ui.SetButtonInteractable(ResourcePacksUI.Buttons.MoveUp, enabled && selected && index > 0);
            ui.SetButtonInteractable(ResourcePacksUI.Buttons.MoveDown, enabled && selected && index < enabledReferences.Count - 1);
        }
        private IEnumerable<ResourcePackReference> GetDisabledReferences()
        {
            return references.Except(enabledReferences);
        }
        private bool IsDirty()
        {
            return overridedFile || !enabledReferences.SequenceEqual(Main.ResourcePackManager.GetEnabledLanguagePackList());
        }
        private ResourcePackReference GetLanguagePackReferenceByUI(bool enabled, int index)
        {
            if (enabled)
            {
                return enabledReferences[index];
            }
            else
            {
                var disabled = GetDisabledReferences();
                return disabled.ElementAtOrDefault(index);
            }
        }
        private int GetItemUIIndex(bool enabled, ResourcePackReference reference)
        {
            if (enabled)
            {
                return enabledReferences.IndexOf(reference);
            }
            else
            {
                var disabled = GetDisabledReferences().ToArray();
                return Array.IndexOf(disabled, reference);
            }
        }
        private ResourcePackViewData GetResourcePackViewData(ResourcePackMetadata metadata, ResourcePackReference reference)
        {
            return new ResourcePackViewData()
            {
                name = metadata.name ?? string.Empty,
                description = metadata.description ?? string.Empty,
                icon = metadata.icon,
                outdated = Main.ResourcePackManager.IsOutdated(metadata.dataVersion),
                selected = reference == selectedLanguagePack,
            };
        }
        [TranslateMsg("覆盖语言包的警告，{0}为语言包名称")]
        public const string WARNING_OVERRIDE_LANGUAGE_PACK = "已经存在同名语言包“{0}”，是否覆盖？";
        [TranslateMsg("删除语言包的警告，{0}为语言包名称")]
        public const string WARNING_DELETE_LANGUAGE_PACK = "是否删除语言包“{0}”？";
        [TranslateMsg("语言包中含有过时语言包的警告")]
        public const string WARNING_OUTDATED_LANGAUGE_PACK = "您启用了一些过时的语言包，这些语言包可能无法正常运行，仍然要继续吗？";
        [TranslateMsg("语言包导出失败的警告")]
        public const string ERROR_NOT_SAVED = "导出语言包失败。";
        [TranslateMsg("语言包导入失败的警告")]
        public const string ERROR_FAILED_TO_IMPORT = "导入语言包失败。";
        [TranslateMsg("语言包导出成功的提示，{0}为路径")]
        public const string HINT_SAVED = "语言包已导出至{0}。";

        public MainManager Main => MainManager.Instance;
        [SerializeField]
        private AddonsController addons = null!;
        [SerializeField]
        private ResourcePacksUI ui = null!;
        [SerializeField]
        private float maxRefreshInterval = 1;
        private bool overridedFile;
        private ResourcePackReference? selectedLanguagePack;
        private List<ResourcePackReference> enabledReferences = new List<ResourcePackReference>();
        private List<ResourcePackReference> references = new List<ResourcePackReference>();
        private float refreshInterval;

    }
}
